{
  "name": "Teledyne LeCroy MAUI数字示波器",
  "name_en": "Teledyne LeCroy MAUI Digital Oscilloscope",
  "manufacturer": "Teledyne LeCroy",
  "description": "这是一类配备 MAUI 用户界面的中高端数字示波器，用于采集、显示和分析高速电信号波形。它通常支持多通道输入、触发控制、自动测量、统计分析、数学运算和参考波形管理，常用于电子电路、通信、嵌入式系统和通用实验室调试测试。",
  "description_en": "This is a family of medium- to high-end digital oscilloscopes with the MAUI user interface, used to capture, display, and analyze high-speed electrical waveforms. They typically support multi-channel acquisition, trigger control, automatic measurements, statistical analysis, math functions, and reference waveform handling for electronics, communications, embedded systems, and general laboratory debugging and test work.",
  "tag_hints": [
    "digital oscilloscope",
    "high-speed waveform acquisition",
    "triggered measurements",
    "waveform math",
    "FFT analysis",
    "measurement statistics",
    "reference waveforms"
  ],
  "actions": [
    {
      "action_name": "auto-channel",
      "description": "访问指定示波器通道。",
      "description_en": "Access a specified oscilloscope channel."
    },
    {
      "action_name": "auto-math",
      "description": "访问数学运算通道或数学函数。",
      "description_en": "Access a math channel or math function."
    },
    {
      "action_name": "auto-measurement",
      "description": "访问指定测量项目或测量槽位。",
      "description_en": "Access a specified measurement item or measurement slot."
    },
    {
      "action_name": "auto-ref",
      "description": "访问参考波形。",
      "description_en": "Access a reference waveform."
    },
    {
      "action_name": "auto-number_channels",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    },
    {
      "action_name": "auto-number_functions",
      "description": "获取数学函数数量。",
      "description_en": "Get the number of math functions."
    },
    {
      "action_name": "auto-number_measurements",
      "description": "获取测量项目数量。",
      "description_en": "Get the number of measurement items."
    },
    {
      "action_name": "auto-self_test",
      "description": "运行仪器自检。",
      "description_en": "Run the instrument self-test."
    },
    {
      "action_name": "auto-show_id",
      "description": "获取仪器标识信息。",
      "description_en": "Get the instrument identification information."
    },
    {
      "action_name": "auto-show_options",
      "description": "获取已安装选件信息。",
      "description_en": "Get the installed option information."
    },
    {
      "action_name": "auto-time_div",
      "description": "获取或设置水平时基每格时间。",
      "description_en": "Get or set the horizontal time scale per division."
    },
    {
      "action_name": "auto-trigger_delay",
      "description": "获取或设置触发延迟。",
      "description_en": "Get or set the trigger delay."
    },
    {
      "action_name": "auto-trigger_source",
      "description": "获取或设置触发源。",
      "description_en": "Get or set the trigger source."
    },
    {
      "action_name": "auto-trigger_type",
      "description": "获取或设置触发类型。",
      "description_en": "Get or set the trigger type."
    },
    {
      "action_name": "auto-clear_sweeps",
      "description": "清除累计扫掠或统计数据。",
      "description_en": "Clear accumulated sweeps or statistics."
    },
    {
      "action_name": "auto-force_trigger",
      "description": "强制触发一次采集。",
      "description_en": "Force a trigger for an acquisition."
    },
    {
      "action_name": "auto-name",
      "description": "获取或设置名称。",
      "description_en": "Get or set the name."
    },
    {
      "action_name": "auto-read_waveform",
      "description": "读取波形数据。",
      "description_en": "Read waveform data."
    },
    {
      "action_name": "auto-offset",
      "description": "获取或设置垂直偏置。",
      "description_en": "Get or set the vertical offset."
    },
    {
      "action_name": "auto-scale",
      "description": "获取或设置垂直刻度。",
      "description_en": "Get or set the vertical scale."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向示波器发送底层命令。",
      "description_en": "Send a low-level command to the oscilloscope."
    },
    {
      "action_name": "auto-query",
      "description": "向示波器发送查询并读取响应。",
      "description_en": "Send a query to the oscilloscope and read the response."
    },
    {
      "action_name": "auto-operator",
      "description": "获取或设置测量或数学运算类型。",
      "description_en": "Get or set the measurement or math operator."
    },
    {
      "action_name": "auto-statistics",
      "description": "获取或设置统计功能。",
      "description_en": "Get or set the statistics setting."
    },
    {
      "action_name": "auto-delete",
      "description": "删除当前测量项目或数学函数。",
      "description_en": "Delete the current measurement item or math function."
    },
    {
      "action_name": "auto-set_parameter",
      "description": "设置测量或数学功能的输入参数。",
      "description_en": "Set an input parameter for a measurement or math function."
    },
    {
      "action_name": "auto-current_setting",
      "description": "获取当前设置。",
      "description_en": "Get the current setting."
    },
    {
      "action_name": "auto-absolute",
      "description": "将数学函数定义为绝对值运算。",
      "description_en": "Define the math function as an absolute value operation."
    },
    {
      "action_name": "auto-average",
      "description": "将数学函数定义为平均运算。",
      "description_en": "Define the math function as an averaging operation."
    },
    {
      "action_name": "auto-derivative",
      "description": "将数学函数定义为求导运算。",
      "description_en": "Define the math function as a derivative operation."
    },
    {
      "action_name": "auto-difference",
      "description": "将数学函数定义为差值运算。",
      "description_en": "Define the math function as a difference operation."
    },
    {
      "action_name": "auto-envelope",
      "description": "将数学函数定义为包络运算。",
      "description_en": "Define the math function as an envelope operation."
    },
    {
      "action_name": "auto-eres",
      "description": "将数学函数定义为增强分辨率运算。",
      "description_en": "Define the math function as an enhanced resolution operation."
    },
    {
      "action_name": "auto-fft",
      "description": "将数学函数定义为快速傅里叶变换。",
      "description_en": "Define the math function as a fast Fourier transform."
    },
    {
      "action_name": "auto-floor",
      "description": "将数学函数定义为向下取整运算。",
      "description_en": "Define the math function as a floor operation."
    },
    {
      "action_name": "auto-integral",
      "description": "将数学函数定义为积分运算。",
      "description_en": "Define the math function as an integral operation."
    },
    {
      "action_name": "auto-invert",
      "description": "将数学函数定义为反相运算。",
      "description_en": "Define the math function as an inversion operation."
    },
    {
      "action_name": "auto-product",
      "description": "将数学函数定义为乘积运算。",
      "description_en": "Define the math function as a product operation."
    },
    {
      "action_name": "auto-ratio",
      "description": "将数学函数定义为比值运算。",
      "description_en": "Define the math function as a ratio operation."
    },
    {
      "action_name": "auto-reciprocal",
      "description": "将数学函数定义为倒数运算。",
      "description_en": "Define the math function as a reciprocal operation."
    },
    {
      "action_name": "auto-rescale",
      "description": "将数学函数定义为重缩放运算。",
      "description_en": "Define the math function as a rescaling operation."
    },
    {
      "action_name": "auto-sinx",
      "description": "将数学函数定义为 sin(x) 运算。",
      "description_en": "Define the math function as a sin(x) operation."
    },
    {
      "action_name": "auto-square",
      "description": "将数学函数定义为平方运算。",
      "description_en": "Define the math function as a square operation."
    },
    {
      "action_name": "auto-square_root",
      "description": "将数学函数定义为平方根运算。",
      "description_en": "Define the math function as a square-root operation."
    },
    {
      "action_name": "auto-sum",
      "description": "将数学函数定义为求和运算。",
      "description_en": "Define the math function as a sum operation."
    },
    {
      "action_name": "auto-trend",
      "description": "将数学函数定义为趋势运算。",
      "description_en": "Define the math function as a trend operation."
    },
    {
      "action_name": "auto-roof",
      "description": "将数学函数定义为向上取整运算。",
      "description_en": "Define the math function as a ceiling operation."
    }
  ]
}

